use super::constraints::SignedConstraints;
use alloy_consensus::{SignableTransaction};
use alloy_eips::{Decodable2718, Encodable2718};
use alloy_primitives::{TxHash, B256};
use ethereum_consensus::{
    bellatrix::presets::minimal::Transaction, phase0::Bytes32, ssz::prelude::*,
};
use reth_primitives::{PooledTransaction, TransactionSigned};
use tracing::{info, warn};
use tree_hash::Hash256;

pub const MAX_CONSTRAINTS_PER_SLOT: usize = 256;

pub type ExecutionPayloadTransactions = List<Transaction, MAX_TRANSACTIONS_PER_PAYLOAD>;

const MAX_BYTES_PER_TRANSACTION: usize = 1_073_741_824; // 1 GiB
const MAX_TRANSACTIONS_PER_PAYLOAD: usize = 1_048_576; // 2^20

pub type HashTreeRootType = Hash256;
/// List of transaction hashes and the corresponding hash tree roots of the raw transactions.
pub type ConstraintsProofData = Vec<(TxHash, HashTreeRootType)>;

#[derive(Debug, Clone, serde::Deserialize, serde::Serialize)]
pub struct SignedConstraintsWithProofData {
    pub signed_constraints: SignedConstraints,
    pub proof_data: ConstraintsProofData,
}

impl TryFrom<SignedConstraints> for SignedConstraintsWithProofData {
    type Error = ProofError;

    fn try_from(value: SignedConstraints) -> Result<Self, ProofError> {
        let mut transactions = Vec::with_capacity(value.message.transactions.len());
        for transaction in value.message.transactions.iter() {
            let tx = PooledTransaction::decode_2718(&mut transaction.as_slice())
                .map_err(|e| ProofError::DecodingFailed(e.to_string()))?;
            let tx_hash = *tx.tx_hash();

            let raw_tx = if tx.is_eip4844() {
                // If the transaction is of type 3, we need to remove the optional sidecar
                // before computing the hash tree root.
                let (tx_with_sidecar, sig, _) = tx.as_eip4844().unwrap().clone().into_parts();
                let tx_without_sidecar = tx_with_sidecar.tx.into_signed(sig);
                Transaction::try_from(tx_without_sidecar.encoded_2718().as_ref()).unwrap()
            } else {
                transaction.clone()
            };

            let root = raw_tx
                .hash_tree_root()
                .map_err(|e| ProofError::DecodingFailed(e.to_string()))?;
            let root = Hash256::from_slice(root.as_slice());

            transactions.push((tx_hash, root));
        }

        Ok(Self {
            signed_constraints: value,
            proof_data: transactions,
        })
    }
}

/// Returns the length of the leaves that need to be proven (i.e.  transactions).
fn total_leaves(constraints: &[&ConstraintsProofData]) -> usize {
    constraints.iter().map(|c| c.len()).sum()
}

#[derive(Debug, thiserror::Error)]
pub enum ProofError {
    #[error("Leaves and indices length mismatch")]
    LengthMismatch,
    #[error("Mismatch in provided leaves and leaves to prove")]
    LeavesMismatch,
    #[error("Hash not found in constraints cache: {0:?}")]
    MissingHash(TxHash),
    #[error("Proof verification failed")]
    VerificationFailed,
    #[error("Decoding failed: {0}")]
    DecodingFailed(String),
    #[error("Failed to generate proof")]
    FailedToGenerateProof,
}

/// InclusionProof is a Merkle Multiproof of inclusion of a set of TransactionHashes
#[derive(Debug, Clone, PartialEq, Serializable, serde::Serialize, serde::Deserialize)]
pub struct InclusionProofs {
    pub transaction_hashes: List<Bytes32, MAX_CONSTRAINTS_PER_SLOT>,
    pub generalized_indexes: List<u64, MAX_CONSTRAINTS_PER_SLOT>,
    pub merkle_hashes: List<Bytes32, MAX_TRANSACTIONS_PER_PAYLOAD>,
}

impl InclusionProofs {
    /// Returns the total number of leaves in the tree.
    pub fn total_leaves(&self) -> usize {
        self.transaction_hashes.len()
    }

    pub fn as_ssz_bytes(&self) -> Vec<u8> {
        ssz_rs::serialize(self).unwrap()
    }
}

fn constraints_to_signed_txs(constraints: &Vec<SignedConstraints>) -> Vec<TransactionSigned> {
    constraints
        .iter()
        .map(|c| {
            c.message
                .transactions
                .to_vec()
                .iter()
                .map(|tx| {
                    let tx = PooledTransaction::decode_2718(&mut tx.as_slice()).unwrap();
                    TransactionSigned::from(tx)
                })
                .collect::<Vec<_>>()
        })
        .flatten()
        .collect()
}

pub fn generate_inclusion_proofs(
    payload_transactions: Vec<TransactionSigned>,
    constraints: &Vec<SignedConstraints>,
    verify_proof: bool,
) -> Result<InclusionProofs, ProofError> {
    let mut inner: Vec<List<u8, MAX_BYTES_PER_TRANSACTION>> =
        Vec::with_capacity(payload_transactions.len());
    for (i, tx) in payload_transactions.clone().into_iter().enumerate() {
        let mut tx_bytes = Vec::new();
        tx.encode_2718(&mut tx_bytes);

        let tx_list = List::<u8, MAX_BYTES_PER_TRANSACTION>::try_from(tx_bytes).expect(&format!(
            "Failed to convert Vec<u8> to List<u8, {}> at index {}",
            MAX_BYTES_PER_TRANSACTION, i
        ));

        inner.push(tx_list);
    }

    let ssz_txs =
        List::<List<u8, MAX_BYTES_PER_TRANSACTION>, MAX_TRANSACTIONS_PER_PAYLOAD>::try_from(inner)
            .expect("Failed to convert Vec<List<u8, MAX_BYTES_PER_TRANSACTION>> to outer List");

    let root = ssz_txs.hash_tree_root().unwrap();

    let constraint_txs = constraints_to_signed_txs(constraints);

    let mut indexes: Vec<usize> = Vec::with_capacity(constraint_txs.len());
    for constraint in constraint_txs.clone() {
        let tx_hash = constraint.hash();
        let index = payload_transactions
            .iter()
            .position(|tx| tx.hash() == tx_hash)
            .ok_or(ProofError::MissingHash(*tx_hash))?;
        indexes.push(index);
    }
    info!(
        num_of_txs = payload_transactions.len(),
        constraints_len = indexes.len(),
        "Generating inclusion proofs"
    );

    let indices: Vec<[PathElement; 1]> = indexes
        .into_iter()
        .map(|idx| [PathElement::from(idx)])
        .collect();
    let paths: Vec<&[PathElement]> = indices.iter().map(|p| &p[..]).collect();

    let (multi_proof, witness) = ssz_txs
        .multi_prove(&paths)
        .map_err(|_| ProofError::FailedToGenerateProof)?;
    assert_eq!(root, witness);

    ssz_rs::multiproofs::verify_merkle_multiproof(
        &multi_proof.leaves,
        &multi_proof.branch,
        &multi_proof.indices,
        root,
    )
    .map_err(|_| ProofError::VerificationFailed)?;

    let inclusion_proof = create_inclusion_proof_from_multi_proof(multi_proof, constraint_txs)?;

    // Verify the multiproof if requested
    if verify_proof {
        let proof_data_vec: Vec<SignedConstraintsWithProofData> = constraints
            .iter()
            .map(|c| {
                SignedConstraintsWithProofData::try_from(c.clone())
                    .expect("Failed to convert to SignedConstraintsWithProofData")
            })
            .collect();

        let constraints_proofs_data: Vec<&ConstraintsProofData> = proof_data_vec
            .iter()
            .map(|proof_data| &proof_data.proof_data)
            .collect();
        match verify_inclusion_proofs(
            &constraints_proofs_data,
            &inclusion_proof,
            B256::from_slice(root.as_slice()),
        ) {
            Ok(_) => {
                info!("Inclusion proofs verification successfull")
            }
            Err(err) => {
                warn!(?err, "Failed to verify inclusion proofs")
            }
        }
    }

    Ok(inclusion_proof)
}

/// Create InclusionProofs from a MultiProof and a list of constraints
fn create_inclusion_proof_from_multi_proof(
    multi_proof: ssz_rs::proofs::MultiProof,
    constraints: Vec<TransactionSigned>,
) -> Result<InclusionProofs, ProofError> {
    let mut generalised_indexes = Vec::with_capacity(multi_proof.indices.len());
    let mut merkle_hashes = Vec::with_capacity(multi_proof.branch.len());
    let mut transaction_hashes = Vec::with_capacity(constraints.len());

    for idx in multi_proof.indices {
        generalised_indexes.push(idx as u64);
    }

    for hash in multi_proof.branch {
        merkle_hashes.push(Bytes32::try_from(hash.as_slice()).unwrap());
    }

    for constraint in constraints {
        let tx_hash = constraint.hash();
        transaction_hashes.push(Bytes32::try_from(tx_hash.as_slice()).unwrap());
    }

    Ok(InclusionProofs {
        transaction_hashes: List::try_from(transaction_hashes).unwrap(),
        generalized_indexes: List::try_from(generalised_indexes).unwrap(),
        merkle_hashes: List::try_from(merkle_hashes).unwrap(),
    })
}

pub fn verify_inclusion_proofs(
    constraints_proofs_data: &[&ConstraintsProofData],
    proofs: &InclusionProofs,
    root: B256,
) -> Result<(), ProofError> {
    // Check if the length of the leaves and indices match
    if proofs.transaction_hashes.len() != proofs.generalized_indexes.len() {
        return Err(ProofError::LengthMismatch);
    }

    let total_leaves = total_leaves(constraints_proofs_data);

    // Check if the total leaves matches the proofs provided
    if total_leaves != proofs.total_leaves() {
        return Err(ProofError::LeavesMismatch);
    }

    // Get all the leaves from the saved constraints
    let mut leaves = Vec::with_capacity(proofs.total_leaves());

    // NOTE: Get the leaves from the constraints cache by matching the saved hashes.
    // We need the leaves in order to verify the multiproof.
    for hash in proofs.transaction_hashes.iter() {
        let mut found = false;
        for constraints_proof in constraints_proofs_data {
            for (saved_hash, leaf) in *constraints_proof {
                if saved_hash.as_slice() == hash.as_slice() {
                    found = true;
                    leaves.push(B256::from(leaf.0));
                    break;
                }
            }
            if found {
                break;
            }
        }

        // If the hash is not found in the constraints cache, return an error
        if !found {
            return Err(ProofError::MissingHash(TxHash::from_slice(hash.as_slice())));
        }
    }

    // Conversions to the correct types (and versions of the same type)
    let leaves = leaves
        .into_iter()
        .map(|h| h.as_slice().try_into().unwrap())
        .collect::<Vec<_>>();
    let merkle_proofs = proofs
        .merkle_hashes
        .to_vec()
        .iter()
        .map(|h| h.as_slice().try_into().unwrap())
        .collect::<Vec<_>>();
    let indexes = proofs
        .generalized_indexes
        .to_vec()
        .iter()
        .map(|h| *h as usize)
        .collect::<Vec<_>>();

    let root = root.as_slice().try_into().expect("Invalid root length");

    // Verify the Merkle multiproof against the root
    let result = ssz_rs::multiproofs::verify_merkle_multiproof(
        leaves.as_slice(),
        merkle_proofs.as_ref(),
        indexes.as_slice(),
        root,
    );
    result.map_err(|_| ProofError::VerificationFailed)?;

    Ok(())
}

